            if($db->tableExists('notifications'))foreach($orderIds as$oid){$no=(string)$db->fetchValue('SELECT public_no FROM orders WHERE id=:id',['id'=>$oid]);$db->execute("DELETE FROM notifications WHERE JSON_UNQUOTE(JSON_EXTRACT(IF(JSON_VALID(data_json),data_json,'{}'),'$.order_id'))=:id",['id'=>(string)$oid]);}
