            if($db->tableExists('quote_selections'))$db->execute('DELETE FROM quote_selections WHERE order_id IN ('.implode(',',array_map('intval',$orderIds)).')');
            if($db->tableExists('assignments'))$db->execute('DELETE FROM assignments WHERE order_id IN ('.implode(',',array_map('intval',$orderIds)).')');
            if($db->tableExists('commission_rule_versions'))$db->execute('DELETE FROM commission_rule_versions WHERE order_id IN ('.implode(',',array_map('intval',$orderIds)).')');
            if($db->tableExists('quote_versions'))$db->execute('DELETE qv FROM quote_versions qv JOIN quotes q ON q.id=qv.quote_id WHERE q.order_id IN ('.implode(',',array_map('intval',$orderIds)).')');
