    private function instance(string $public): array{$r=$this->db->fetch('SELECT * FROM test_instances WHERE BINARY public_id=BINARY :id LIMIT 1',['id'=>trim($public)]);if(!$r)throw new TestCenterException('测试实例不存在。','TEST_INSTANCE_NOT_FOUND',404);return$r;}
    private function outboxCount(int $id,string $no): int{if(!$this->db->tableExists('message_outbox'))return 0;return(int)$this->db->fetchValue('SELECT COUNT(*) FROM message_outbox WHERE payload_json LIKE :id OR payload_json LIKE :no OR business_key LIKE :business',['id'=>'%"order_id":'.$id.'%','no'=>'%'.$no.'%','business'=>'%'.$no.'%']);}
